<div class="section-head"><div><span class="eyebrow">Explore</span><h2>Programming contests</h2><p class="muted">Find approved contests, register, and test your skills.</p></div><?php if(user()&&has_role('ORGANIZER')):?><a class="button" href="<?=e(url('/organizer/contests/create'))?>">+ Create contest</a><?php endif;?></div>
<form class="toolbar" method="get" action="<?=e(url('/contests'))?>"><input name="q" value="<?=e($search)?>" placeholder="Search contests" aria-label="Search contests"><select name="status" aria-label="Contest status"><option value="">All statuses</option><?php foreach(['UPCOMING','ONGOING','COMPLETED','CANCELLED'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="button">Filter</button></form>
<section class="contest-grid"><?php foreach($contests as $contest):?><article class="card contest-card"><div class="section-head"><span class="eyebrow"><?=e($contest['visibility'])?></span><span class="badge badge-<?=e(strtolower($contest['lifecycle_status']))?>"><?=e($contest['lifecycle_status'])?></span></div><h2><?=e($contest['contest_title'])?></h2><p class="muted"><?=e($contest['description'])?></p><div class="contest-meta"><span>◷ <?=e($contest['start_time'])?></span><span>⌛ <?=e($contest['duration_minutes'])?> minutes</span><span>♙ <?=e($contest['participant_count'])?> registered</span></div><div class="actions"><a class="button button-block" href="<?=e(url('/contests/'.$contest['contest_id']))?>">View details</a></div></article><?php endforeach;?><?php if(!$contests):?><article class="card empty">No contests match these filters.</article><?php endif;?></section>
